// Actual product UI + real local API; delay/drop only responses, never send to production.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'/Users/toozservis/Developer/evidence-web-qa-runtime/node_modules/playwright');
const origin=process.env.MESSAGE_QA_ORIGIN||'http://127.0.0.1:18922';assert.equal(new URL(origin).hostname,'127.0.0.1');
const output=process.env.MESSAGE_QA_OUTPUT||'/Users/toozservis/Developer/evidence-message-send-state-20261105/evidence/browser';fs.mkdirSync(output,{recursive:true});
(async()=>{
 const users=(await(await fetch(origin+'/qa/setup')).json()).web.users,checks=[],errors=[],contexts=[],requests=[],run='SEND-STATE-QA '+Date.now();
 const browser=await chromium.launch({channel:'chrome',headless:true});let last;
 const history=async role=>{const r=await fetch(origin+'/admin-api/control-center/messages/accounts/'+users[role].id+'?limit=100',{headers:{Authorization:'Bearer '+users.admin.jwt}});assert(r.ok);return (await r.json()).items;};
 const dialog=p=>p.locator('dialog.message-dialog');
 const success=p=>dialog(p).getByText('Zpráva je uložená a odeslaná do konverzace. Stav přečtení se doplní po jejím zobrazení.',{exact:true}).waitFor();
 const save=async(p,name)=>{await p.screenshot({path:path.join(output,name+'.png')});fs.writeFileSync(path.join(output,name+'.txt'),await p.locator('body').innerText());};
 async function open(role){const c=await browser.newContext({viewport:{width:1100,height:950},locale:'cs-CZ'});contexts.push(c);await c.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());await c.addInitScript(({u,admin})=>{sessionStorage.setItem(admin?'adminAccessToken':'customerWebAccessToken',u.jwt);sessionStorage.setItem(admin?'adminRole':'customerWebRole',u.role);},{u:users[role],admin:role==='admin'});const p=last=await c.newPage();p.on('pageerror',e=>errors.push(e.message));await p.goto(origin+(role==='admin'?'/web_admin/index.html#users':'/web/customer.html'));if(role==='admin'){await p.locator('button[data-section="users"]').click();await p.locator('[data-user-id="'+users.user.id+'"]').click();await p.getByRole('button',{name:'Napsat zprávu',exact:true}).click();}else{await p.getByRole('button',{name:'Nastavení',exact:true}).click();await p.getByRole('button',{name:'Otevřít zprávy administrace',exact:true}).click();}await dialog(p).getByLabel('Text zprávy',{exact:true}).waitFor();return p;}
 async function heldPost(p,endpoint,drop=false){let release,ready;const gate=new Promise(r=>release=r),started=new Promise(r=>ready=r);await p.route('**'+endpoint,async route=>{if(route.request().method()!=='POST')return route.continue();requests.push(JSON.parse(route.request().postData()));const response=await route.fetch();ready();await gate;if(drop)await route.abort('failed');else await route.fulfill({response});},{times:1});return {started,release};}
 async function inFlight(p){await dialog(p).getByText('Odesílám zprávu…',{exact:true}).waitFor();assert.equal(await dialog(p).getByRole('button',{name:'Zopakovat stejné odeslání',exact:true}).count(),0);assert(!await dialog(p).innerText().then(t=>t.includes('Výsledek odeslání zatím není potvrzený')));assert(await dialog(p).getByRole('button',{name:'Odesílám…',exact:true}).isDisabled());assert(await dialog(p).getByLabel('Text zprávy',{exact:true}).isDisabled());assert.equal(await dialog(p).locator('.message-notice[role="alert"]').count(),0);}
 async function send(p,body){await dialog(p).getByLabel('Text zprávy',{exact:true}).fill(body);await dialog(p).getByRole('button',{name:'Odeslat zprávu',exact:true}).click();}
 try{
  const admin=await open('admin'),endpoint='/admin-api/control-center/messages/accounts/'+users.user.id;
  const normal=run+' normální zpožděné odeslání',first=await heldPost(admin,endpoint);await send(admin,normal);await first.started;await inFlight(admin);await save(admin,'01-admin-sending');first.release();await success(admin);assert.equal((await history('user')).filter(x=>x.body===normal).length,1);assert(!await dialog(admin).getByRole('button',{name:'Odeslat zprávu',exact:true}).isDisabled());checks.push('Admin delayed successful POST shows only neutral sending, no retry/uncertain error, and persists one message');
  const retryBody=run+' ztracená odpověď',lost=await heldPost(admin,endpoint,true);await send(admin,retryBody);await lost.started;await inFlight(admin);lost.release();await dialog(admin).getByRole('button',{name:'Zopakovat stejné odeslání',exact:true}).waitFor();assert(await dialog(admin).getByRole('button',{name:'Odeslat zprávu',exact:true}).isDisabled());assert(await dialog(admin).getByLabel('Text zprávy',{exact:true}).isDisabled());assert.equal((await history('user')).filter(x=>x.body===retryBody).length,1);await save(admin,'02-admin-uncertain');checks.push('Only an actual lost response exposes uncertain state and Retry; original draft/send remain locked');
  const previous=requests.at(-1),retry=await heldPost(admin,endpoint);await dialog(admin).getByRole('button',{name:'Zopakovat stejné odeslání',exact:true}).click();await retry.started;await inFlight(admin);assert.deepEqual(requests.at(-1),previous);retry.release();await success(admin);assert.equal((await history('user')).filter(x=>x.body===retryBody).length,1);checks.push('Retry returns to neutral sending, clears former alert and reuses exact UUID/payload without duplication');
  const rejected=run+' zamítnuté odeslání';await admin.route('**'+endpoint,route=>route.request().method()==='POST'?route.fulfill({status:403,contentType:'application/json',body:JSON.stringify({detail:'QA: přístup byl zamítnut.'})}):route.continue(),{times:1});await send(admin,rejected);await dialog(admin).getByText('QA: přístup byl zamítnut.',{exact:true}).waitFor();assert.equal(await dialog(admin).getByRole('button',{name:'Zopakovat stejné odeslání',exact:true}).count(),0);assert(!await dialog(admin).getByRole('button',{name:'Odeslat zprávu',exact:true}).isDisabled());assert.equal(await dialog(admin).getByLabel('Text zprávy',{exact:true}).inputValue(),rejected);assert.equal((await history('user')).filter(x=>x.body===rejected).length,0);checks.push('Definitive 403 displays its real error, preserves editable draft, does not falsely offer uncertain retry');
  const refreshFailure=run+' uložená zpráva s chybou následného načtení';await admin.route('**'+endpoint+'?limit=50',route=>route.fulfill({status:403,contentType:'application/json',body:JSON.stringify({detail:'QA: následné načtení historie selhalo.'})}),{times:1});await send(admin,refreshFailure);await dialog(admin).getByText('QA: následné načtení historie selhalo.',{exact:true}).waitFor();assert.equal(await dialog(admin).getByRole('button',{name:'Zopakovat stejné odeslání',exact:true}).count(),0);assert.equal((await history('user')).filter(x=>x.body===refreshFailure).length,1);checks.push('Already confirmed POST followed by failed history refresh remains one saved message, no null-pending exception or retry');
  for(const role of ['user','service']){const p=await open(role),body=run+' odpověď '+role,hold=await heldPost(p,'/api/v1/admin-messages');await send(p,body);await hold.started;await inFlight(p);hold.release();await success(p);assert.equal((await history(role)).filter(x=>x.body===body).length,1);checks.push(role+': same sender state used for private reply, actual API records one message');}
  assert.deepEqual(errors,[]);const result={status:'PASS',at:new Date().toISOString(),origin,checks,source_sha256:createHash('sha256').update(fs.readFileSync(path.join(__dirname,'../../web/admin-messages.js'))).digest('hex'),limits:['Synthetic JWT precondition, real loopback API/product HTML','Response latency/drop and definite rejection are deliberate transport test injections','No real recipients, production writes or provider sending']};fs.writeFileSync(path.join(output,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
 }catch(error){if(last){await save(last,'failure');fs.writeFileSync(path.join(output,'failure-error.txt'),error.stack);}throw error;}finally{for(const c of contexts)await c.close();await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
